    h,w=len(di),len(di[0])
    bgv=C2(x for r in di for x in r).most_common(1)[0][0]
    mk={(i,j) for i in range(h) for j in range(w) if di[i][j]!=bgv}
    H=hullpts(sorted(mk))
    segs=[]
    for a,b in zip(H,H[1:]):
        dr,dc=b[0]-a[0],b[1]-a[1]
        g=math.gcd(abs(dr),abs(dc)) or 1
        s_r=(dr if dc==0 else 0,0)
        s_d=(0,(dc if dr==0 else 0))
        steps=(s_r if s_r!=() else s_d)
        # walk from a toward b
        sr=s_r[0]; sc=s_d[1]
        if g>1: sr//=g; sc//=g
        for k in range(1,g):
            r=a[0]+k*sr; c=a[1]+k*sc
            if a[0]<=r<=b[0] and a[1]<=c<=b[1]:  # keep middle points only, exclude endpoints? try incl
                pass
        segs.append((a,b,sr,sc))
    out=[r[:] for r in di]
    for (a,b,sr,sc) in segs:
        r,c=a
        while (r,c)!=b:
            r+=sr; c+=sc
            if di[r][c]==bgv: out[r][c]=2
    return out
